/**
 * Warna status Invoice Motor.
 *
 * Indikator baris SESUAI Frappe core (`frappe.get_indicator`): doctype ini punya
 * workflow "Invoice Unit" dengan `override_status = 0`, sehingga indikatornya =
 * field `workflow_state`, berwarna dari `style` master Workflow State (BUKAN dari
 * Document States doctype). Mapping style→warna mengikuti indicator.js core:
 *   Success→green, Warning→orange, Danger→red, Primary→blue, Info→light-blue.
 *
 * `status_invoice` (Unpaid/Paid/…) ditampilkan sebagai chip sekunder dengan warna
 * dari Document States doctype (kolom in_list_view yang bold di desk).
 */

// ---- workflow_state (indikator utama) — warna dari Workflow State.style ------
const WF_STATE_COLOR = {
	Draft: 'gray', // style: (kosong)
	'Request Approval': 'orange', // Warning
	Approved: 'green', // Success
	Cancelled: 'orange', // Warning
}
export const STATUS_OPTIONS = ['Draft', 'Request Approval', 'Approved', 'Cancelled']

export function statusColor(state) {
	if (WF_STATE_COLOR[state]) return WF_STATE_COLOR[state]
	const s = String(state || '')
	if (/Reject|Cancel|Danger/i.test(s)) return 'red'
	if (/Approv|Success|Paid|Done/i.test(s)) return 'green'
	if (/Request|Warning|Pending/i.test(s)) return 'orange'
	return 'gray'
}

// ---- status_invoice (chip sekunder) — warna dari Document States -------------
const INVOICE_STATE_COLOR = {
	Unpaid: 'red',
	'Partly Paid': 'orange',
	Paid: 'green',
	Overdue: 'purple',
	'Partial Return': 'yellow',
	'Full Return': 'gray',
}
export const INVOICE_STATUS_OPTIONS = [
	'Unpaid',
	'Partly Paid',
	'Paid',
	'Overdue',
	'Partial Return',
	'Full Return',
]
export function invoiceStatusColor(status) {
	return INVOICE_STATE_COLOR[status] || 'gray'
}

// ---- Palet pill & dot -------------------------------------------------------
const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	'light-blue': 'bg-ui-surface-sky-200 text-ui-ink-sky-800',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	yellow: 'bg-ui-surface-yellow-100 text-ui-ink-yellow-800',
	purple: 'bg-ui-surface-purple-100 text-ui-ink-purple-700',
}
const DOT = {
	gray: 'border-ui-line-gray-400',
	blue: 'border-ui-line-blue-500',
	'light-blue': 'border-ui-line-sky-500',
	orange: 'border-ui-line-orange-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
	yellow: 'border-ui-line-yellow-500',
	purple: 'border-ui-line-purple-500',
}

export function statusPillClass(state) {
	return PILL[statusColor(state)] || PILL.gray
}
export function statusDotClass(state) {
	return DOT[statusColor(state)] || DOT.gray
}
export function invoiceStatusPillClass(status) {
	return PILL[invoiceStatusColor(status)] || PILL.gray
}
export function invoiceStatusDotClass(status) {
	return DOT[invoiceStatusColor(status)] || DOT.gray
}
